insert or ignore into essential_oils (id, slug, name, botanical_name, family, scent_note, scent_profile, overview, common_uses, mood_slugs, blends_well_with, safety_note, color) values ('oil-palmarosa', 'palmarosa', 'パルマローザ', 'Cymbopogon martinii', 'イネ科', 'ミドル', 'ローズ調、草、軽い甘さ', 'ローズに似た明るい草花の香り。フローラルを軽くしたい時に使いやすい精油です。', '["バランスの良い香り","軽いフローラル","気分転換"]', '["relax","happy"]', '["ゼラニウム","ラベンダー","ベルガモット","シダーウッド"]', '香りが広がりやすいため、少量から調整してください。', '#d9b4a8'); insert or ignore into essential_oils (id, slug, name, botanical_name, family, scent_note, scent_profile, overview, common_uses, mood_slugs, blends_well_with, safety_note, color) values ('oil-juniper-berry', 'juniper-berry', 'ジュニパーベリー', 'Juniperus communis', 'ヒノキ科', 'ミドル', '森林、ドライ、すっきり', 'ドライで透明感のある森林調。リフレッシュやウッディ系ブレンドの橋渡しに使いやすい香りです。', '["リフレッシュ","森林感","ドライな印象"]', '["refresh","focus"]', '["グレープフルーツ","ローズマリー","シダーウッド","ラベンダー"]', '持病や妊娠中など体調に不安がある場合は専門家に確認してください。', '#9aae9d'); insert or ignore into essential_oils (id, slug, name, botanical_name, family, scent_note, scent_profile, overview, common_uses, mood_slugs, blends_well_with, safety_note, color) values ('oil-cypress', 'cypress', 'サイプレス', 'Cupressus sempervirens', 'ヒノキ科', 'ミドル', '針葉樹、ドライ、端正', 'すっきりとした針葉樹の香り。甘さを抑えた落ち着いたブレンドに向きます。', '["呼吸を整えたい気分","森林調","端正な印象"]', '["refresh","relax"]', '["ベルガモット","ジュニパーベリー","ラベンダー","フランキンセンス"]', '香りがドライに出やすいため、柑橘や花と合わせると使いやすくなります。', '#8ea28f'); insert or ignore into essential_oils (id, slug, name, botanical_name, family, scent_note, scent_profile, overview, common_uses, mood_slugs, blends_well_with, safety_note, color) values ('oil-hinoki', 'hinoki', 'ヒノキ', 'Chamaecyparis obtusa', 'ヒノキ科', 'ベース', '和の木、落ち着き、清潔感', '日本らしい木の香り。深呼吸したくなる空間や、落ち着いた和の印象づくりに合います。', '["落ち着いた空間","深呼吸","和のブレンド"]', '["relax","refresh"]', '["ユーカリ","フランキンセンス","ベルガモット","ラベンダー"]', '木部・枝葉など部位で香りが異なるため、製品ごとの印象を確認してください。', '#b99f78'); insert or ignore into essential_oils (id, slug, name, botanical_name, family, scent_note, scent_profile, overview, common_uses, mood_slugs, blends_well_with, safety_note, color) values ('oil-ginger', 'ginger', 'ジンジャー', 'Zingiber officinale', 'ショウガ科', 'ミドル', '温かい、スパイシー、ドライ', '温かみのあるスパイス調。柑橘と合わせると元気な印象のブレンドになります。', '["元気を出したい時","温かい印象","スパイスアクセント"]', '["energy","refresh"]', '["オレンジ","ライム","レモングラス","シダーウッド"]', '刺激を感じる場合があるため、肌使用では低濃度から確認してください。', '#c79a67'); insert or ignore into essential_oils (id, slug, name, botanical_name, family, scent_note, scent_profile, overview, common_uses, mood_slugs, blends_well_with, safety_note, color) values ('oil-black-pepper', 'black-pepper', 'ブラックペッパー', 'Piper nigrum', 'コショウ科', 'ミドル', 'スパイシー、温かい、ドライ', 'ピリッとした温かみのある香り。重いウッディや柑橘にアクセントを加えます。', '["元気な印象","温かみ","アクセント"]', '["energy","focus"]', '["グレープフルーツ","ローズマリー","フランキンセンス","ジンジャー"]', '刺激が出る場合があります。少量から使用してください。', '#8a7668'); insert or ignore into essential_oils (id, slug, name, botanical_name, family, scent_note, scent_profile, overview, common_uses, mood_slugs, blends_well_with, safety_note, color) values ('oil-basil', 'basil', 'バジル', 'Ocimum basilicum', 'シソ科', 'ミドル', 'ハーバル、甘さ、スパイス感', '甘さのあるハーブ調。集中系ブレンドにやわらかな奥行きを加えます。', '["作業前","ハーバルブレンド","気分転換"]', '["focus","refresh"]', '["レモン","ローズマリー","ラベンダー","ペパーミント"]', '種類により成分が異なります。妊娠中や持病がある場合は専門家に確認してください。', '#8bad75'); insert or ignore into essential_oils (id, slug, name, botanical_name, family, scent_note, scent_profile, overview, common_uses, mood_slugs, blends_well_with, safety_note, color) values ('oil-marjoram', 'marjoram', 'マジョラム', 'Origanum majorana', 'シソ科', 'ミドル', '温かいハーブ、やさしい、少しスパイシー', '温かみのある穏やかなハーブ調。夜のリラックスブレンドにやさしさを足します。', '["夜のくつろぎ","温かい印象","ハーバル調"]', '["relax","sleep"]', '["ラベンダー","ベルガモット","シダーウッド","クラリセージ"]', '眠気を感じる場合があるため、車の運転前などは避けてください。', '#b8b47c'); insert or ignore into essential_oils (id, slug, name, botanical_name, family, scent_note, scent_profile, overview, common_uses, mood_slugs, blends_well_with, safety_note, color) values ('oil-vetiver', 'vetiver', 'ベチバー', 'Vetiveria zizanoides', 'イネ科', 'ベース', '土、根、重厚、スモーキー', '深く重い根の香り。香りの土台や静かな夜のブレンドにごく少量使います。', '["深い落ち着き","香りの固定","重厚感"]', '["relax","sleep"]', '["ラベンダー","サンダルウッド","ベルガモット","フランキンセンス"]', '非常に重く残るため、少量から調整してください。', '#8b735f'); insert or ignore into essential_oils (id, slug, name, botanical_name, family, scent_note, scent_profile, overview, common_uses, mood_slugs, blends_well_with, safety_note, color) values ('oil-myrrh', 'myrrh', 'ミルラ', 'Commiphora myrrha', 'カンラン科', 'ベース', '樹脂、ほろ苦い、静か', 'ほろ苦く静かな樹脂の香り。フランキンセンスと合わせると奥行きのある印象になります。', '["静かな時間","樹脂系ブレンド","余韻づくり"]', '["relax"]', '["フランキンセンス","サンダルウッド","ベルガモット","ラベンダー"]', '粘度が高い場合があります。ディフューザーや器具の仕様に注意してください。', '#a98265'); insert or ignore into essential_oils (id, slug, name, botanical_name, family, scent_note, scent_profile, overview, common_uses, mood_slugs, blends_well_with, safety_note, color) values ('oil-clove', 'clove', 'クローブ', 'Syzygium aromaticum', 'フトモモ科', 'ミドル', '甘いスパイス、温かい、強い', '甘く強いスパイス調。冬らしい香りや柑橘ブレンドに少量で温かみを加えます。', '["温かい香り","アクセント","季節感"]', '["energy"]', '["オレンジ","シナモン","ジンジャー","シダーウッド"]', '刺激が強い精油です。肌使用は特に低濃度で、敏感肌は避ける判断も必要です。', '#9b654c'); insert or ignore into essential_oils (id, slug, name, botanical_name, family, scent_note, scent_profile, overview, common_uses, mood_slugs, blends_well_with, safety_note, color) values ('oil-cinnamon-leaf', 'cinnamon-leaf', 'シナモンリーフ', 'Cinnamomum zeylanicum', 'クスノキ科', 'ミドル', '甘いスパイス、温かい、濃厚', '甘く温かいスパイスの香り。柑橘やウッディと合わせると季節感が出ます。', '["温かみ","冬のブレンド","少量アクセント"]', '["energy","happy"]', '["オレンジ","クローブ","ジンジャー","フランキンセンス"]', '刺激が強いため、肌使用は慎重に。少量から調整してください。', '#b16f4f'); insert or ignore into essential_oils (id, slug, name, botanical_name, family, scent_note, scent_profile, overview, common_uses, mood_slugs, blends_well_with, safety_note, color) values ('oil-spearmint', 'spearmint', 'スペアミント', 'Mentha spicata', 'シソ科', 'トップ', 'やさしいミント、甘い、軽い', 'ペパーミントよりやわらかいミント調。軽い清涼感を出したい時に使いやすい精油です。', '["軽いリフレッシュ","朝の香り","ミントの調整"]', '["refresh","focus"]', '["レモン","ラベンダー","ローズマリー","グレープフルーツ"]', 'ミント系として刺激に注意し、少量から使ってください。', '#9fd0b6');
